const fs = require('fs');
const babel = require('@babel/core');
const path = require('path').resolve(__dirname, '../..');
const input = process.argv[2];
if (!input) throw new Error('Pass the directory containing the extracted upstream files');
const out = path + '/app/src/main/assets/adguard';
const notices = path + '/third_party/adguard';
fs.mkdirSync(out, { recursive:true }); fs.mkdirSync(notices, { recursive:true });
const options={presets:[[require('@babel/preset-env'),{targets:{chrome:'37'},modules:false}]],comments:true,compact:false};
const extended = fs.readFileSync(input+'/extended/extended-css.js','utf8');
fs.writeFileSync(out+'/extended-css.js',babel.transformSync(extended,options).code);
const data=JSON.parse(fs.readFileSync(input+'/scriptlets/scriptlets.corelibs.json','utf8'));
for(const item of data.scriptlets) item.scriptlet='(function(){'+babel.transformSync('var __pwaScriptlet=('+item.scriptlet+');', {...options,comments:false,compact:true}).code+';return __pwaScriptlet;})()';
fs.writeFileSync(out+'/scriptlets.json',JSON.stringify(data));
fs.copyFileSync(require.resolve('core-js-bundle/minified.js'),out+'/polyfills.js');
fs.copyFileSync(require.resolve('core-js-bundle/LICENSE'),notices+'/CORE-JS-LICENSE');
fs.copyFileSync(input+'/extended/LICENSE',notices+'/ADGUARD-LICENSE');
fs.copyFileSync(notices+'/ADGUARD-LICENSE',out+'/ADGUARD-LICENSE');
fs.copyFileSync(notices+'/CORE-JS-LICENSE',out+'/CORE-JS-LICENSE');
const versions = ['@babel/core','@babel/preset-env','core-js-bundle'].map(name=>name+' '+JSON.parse(fs.readFileSync(require.resolve(name+'/package.json'))).version).join('\n');
fs.writeFileSync(notices+'/BUILD-TOOLS.txt',versions+'\n');
